import{_ as t,o,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Secrets & Configuration Management","description":"","frontmatter":{},"headers":[],"relativePath":"support/secrets_and_config.md","filePath":"support/secrets_and_config.md"}'),s={name:"support/secrets_and_config.md"};function n(r,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="secrets-configuration-management" tabindex="-1">Secrets &amp; Configuration Management <a class="header-anchor" href="#secrets-configuration-management" aria-label="Permalink to &quot;Secrets &amp; Configuration Management&quot;">​</a></h1><p>This document maps out where API keys and Secrets are configured across the Sanjeev AI architecture and details the rotation process.</p><h2 id="secret-locations" tabindex="-1">Secret Locations <a class="header-anchor" href="#secret-locations" aria-label="Permalink to &quot;Secret Locations&quot;">​</a></h2><p>Sanjeev AI relies on several external APIs. The credentials for these APIs are securely stored using Google Cloud Secret Manager and bound to specific Firebase Cloud Functions.</p><h3 id="_1-gemini-api-gemini-api-key" tabindex="-1">1. Gemini API (<code>GEMINI_API_KEY</code>) <a class="header-anchor" href="#_1-gemini-api-gemini-api-key" aria-label="Permalink to &quot;1. Gemini API (`GEMINI_API_KEY`)&quot;">​</a></h3><ul><li><strong>Usage:</strong> Used by AI agents (Parser, Director, Visualizer, Metadata) to generate text, scenes, image prompts, and YouTube metadata.</li><li><strong>Bound Functions:</strong><ul><li><code>parser</code></li><li><code>director</code></li><li><code>visualizer</code></li><li><code>metadata</code></li><li><code>orchestrator</code></li></ul></li><li><strong>Location:</strong> Google Cloud Secret Manager (<code>GEMINI_API_KEY</code>)</li></ul><h3 id="_2-youtube-api-youtube-client-id-youtube-client-secret" tabindex="-1">2. YouTube API (<code>YOUTUBE_CLIENT_ID</code> &amp; <code>YOUTUBE_CLIENT_SECRET</code>) <a class="header-anchor" href="#_2-youtube-api-youtube-client-id-youtube-client-secret" aria-label="Permalink to &quot;2. YouTube API (`YOUTUBE_CLIENT_ID` &amp; `YOUTUBE_CLIENT_SECRET`)&quot;">​</a></h3><ul><li><strong>Usage:</strong> Used by the Publisher and Refresher agents to upload videos to YouTube and refresh OAuth tokens.</li><li><strong>Bound Functions:</strong><ul><li><code>publisher</code></li><li><code>refresher</code></li><li><code>orchestrator</code></li></ul></li><li><strong>Location:</strong> Google Cloud Secret Manager (<code>YOUTUBE_CLIENT_ID</code>, <code>YOUTUBE_CLIENT_SECRET</code>)</li></ul><h3 id="_3-firebase-environment-variables" tabindex="-1">3. Firebase Environment Variables <a class="header-anchor" href="#_3-firebase-environment-variables" aria-label="Permalink to &quot;3. Firebase Environment Variables&quot;">​</a></h3><ul><li><strong>Usage:</strong> Used to configure project-specific settings (e.g., Cloud Renderer URL).</li><li><strong>Locations:</strong><ul><li>Stored in <code>.env</code> or <code>.env.&lt;environment&gt;</code> files (e.g., <code>.env.local</code> for the <code>dev</code> environment).</li><li>Used in functions like <code>exporter</code> (e.g., <code>CLOUD_RENDERER_URL</code>).</li></ul></li></ul><h2 id="rotation-process" tabindex="-1">Rotation Process <a class="header-anchor" href="#rotation-process" aria-label="Permalink to &quot;Rotation Process&quot;">​</a></h2><p>If any secret is compromised or needs regular rotation, follow these steps:</p><h3 id="step-1-update-the-secret-in-google-cloud-secret-manager" tabindex="-1">Step 1: Update the Secret in Google Cloud Secret Manager <a class="header-anchor" href="#step-1-update-the-secret-in-google-cloud-secret-manager" aria-label="Permalink to &quot;Step 1: Update the Secret in Google Cloud Secret Manager&quot;">​</a></h3><ol><li>Go to the <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">Google Cloud Console</a>.</li><li>Navigate to <strong>Security</strong> &gt; <strong>Secret Manager</strong>.</li><li>Select the secret you need to update (e.g., <code>GEMINI_API_KEY</code>).</li><li>Click <strong>New Version</strong> and paste the new API key/secret value.</li><li>Save the new version. (Optional: Disable or destroy the old version if it is compromised).</li></ol><h3 id="step-2-redeploy-affected-cloud-functions" tabindex="-1">Step 2: Redeploy Affected Cloud Functions <a class="header-anchor" href="#step-2-redeploy-affected-cloud-functions" aria-label="Permalink to &quot;Step 2: Redeploy Affected Cloud Functions&quot;">​</a></h3><p>Firebase Cloud Functions only fetch the latest secret values at deployment or cold start (depending on how they are bound). To ensure all active instances use the new secrets, you must redeploy the functions.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Redeploy all functions to apply new secrets</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> functions</span></span></code></pre></div><h3 id="step-3-verify-the-changes" tabindex="-1">Step 3: Verify the Changes <a class="header-anchor" href="#step-3-verify-the-changes" aria-label="Permalink to &quot;Step 3: Verify the Changes&quot;">​</a></h3><ol><li>Run a test workflow in the application.</li><li>Verify that the relevant agent (e.g., the visualizer for <code>GEMINI_API_KEY</code>, or the publisher for YouTube secrets) successfully completes its task without authentication errors.</li><li>Check the Firebase Functions logs for any &quot;unauthenticated&quot; or &quot;permission denied&quot; errors.</li></ol>',19)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
